import { Fragment } from 'react'
import Image from 'next/image'
import Link from 'next/link'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type ImageOverlayHeroProps = {
  title: string
  image: { src: string; alt: string }
  eyebrow?: string
  description?: string
  breadcrumbs?: readonly { label: string; href?: string }[]
  actions?: readonly { label: string; href: string }[]
  align?: 'center' | 'left'
  height?: 'md' | 'lg'
  tone?: AccentTone
  className?: string
}

const heights = {
  md: 'min-h-[52svh] md:min-h-[58svh]',
  lg: 'min-h-[70svh] md:min-h-[78svh]',
}

/** Hero de página interna com imagem de fundo, camadas de gradiente e breadcrumb opcional. */
export function ImageOverlayHero({
  title,
  image,
  eyebrow,
  description,
  breadcrumbs = [],
  actions = [],
  align = 'center',
  height = 'md',
  tone = 'glow',
  className,
}: ImageOverlayHeroProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const centered = align === 'center'
  const line = <span className={cn('h-px w-8', t.line)} aria-hidden />

  return (
    <section
      className={cn(
        'relative flex items-center overflow-hidden',
        heights[height],
        isGlow ? 'bg-[#0e0e0e]' : 'bg-slate-950',
        className,
      )}
    >
      <Image src={image.src} alt={image.alt} fill priority sizes="100vw" className="object-cover" />
      <div
        className={cn(
          'absolute inset-0 bg-gradient-to-r',
          isGlow
            ? 'from-[#121212]/90 via-[#121212]/65 to-[#121212]/30'
            : 'from-slate-950/90 via-slate-950/60 to-slate-950/30',
        )}
        aria-hidden
      />
      <div
        className={cn(
          'absolute inset-0 bg-gradient-to-t via-transparent',
          isGlow ? 'from-[#121212]/70 to-[#121212]/25' : 'from-slate-950/70 to-slate-950/25',
        )}
        aria-hidden
      />

      <div className="container relative z-10 py-20 md:py-24">
        <div className={cn('max-w-3xl text-white', centered && 'mx-auto text-center')}>
          {breadcrumbs.length ? (
            <nav aria-label="Breadcrumb" className="mb-5">
              <ol
                className={cn(
                  'flex flex-wrap items-center gap-2 text-sm',
                  isGlow ? 'text-[#c1c1c1]' : 'text-slate-300',
                  centered && 'justify-center',
                )}
              >
                {breadcrumbs.map((crumb, index) => (
                  <Fragment key={`${crumb.label}-${index}`}>
                    {index > 0 ? <li aria-hidden>/</li> : null}
                    <li>
                      {crumb.href ? (
                        <Link
                          href={crumb.href}
                          className={cn(
                            'transition-colors',
                            isGlow ? 'hover:text-[#ffb0eb]' : 'hover:text-amber-500',
                          )}
                        >
                          {crumb.label}
                        </Link>
                      ) : (
                        <span className="text-white" aria-current="page">
                          {crumb.label}
                        </span>
                      )}
                    </li>
                  </Fragment>
                ))}
              </ol>
            </nav>
          ) : null}

          {eyebrow ? (
            <div className={cn('mb-5 flex items-center gap-3', centered && 'justify-center')}>
              {line}
              <span
                className={cn(
                  'text-[0.65rem] font-medium uppercase tracking-[0.28em]',
                  isGlow ? 'text-[#ffb0eb]' : 'text-amber-500',
                )}
              >
                {eyebrow}
              </span>
              {centered ? line : null}
            </div>
          ) : null}

          <h1
            className={cn(
              'text-3xl font-semibold leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
              isGlow ? cn(t.heading, centered && 'mx-auto') : 'uppercase tracking-wide text-white',
            )}
          >
            {title}
          </h1>

          {description ? (
            <p
              className={cn(
                'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
                isGlow ? 'text-[#c1c1c1]' : 'text-slate-300',
                centered && 'mx-auto',
              )}
            >
              {description}
            </p>
          ) : null}

          {actions.length ? (
            <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
              {actions.map((action) => (
                <AccentButton
                  key={action.href + action.label}
                  href={action.href}
                  tone={isGlow ? 'glow' : 'industrial-dark'}
                >
                  {action.label}
                </AccentButton>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import type { MouseEventHandler, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import type { AccentTone } from './accentTones'

export type AccentButtonProps = {
  children: ReactNode
  href?: string
  tone?: AccentTone
  size?: 'md' | 'lg'
  icon?: ReactNode
  external?: boolean
  type?: 'button' | 'submit'
  disabled?: boolean
  onClick?: MouseEventHandler<HTMLElement>
  className?: string
}

const slideBase =
  'group relative inline-flex w-fit cursor-pointer items-center overflow-hidden rounded-sm font-semibold tracking-wide transition-all duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60'

const slideSizes = {
  md: {
    root: 'h-12 p-1.5 ps-5 pe-14 text-sm hover:ps-14 hover:pe-5',
    icon: 'right-1.5 h-9 w-9 group-hover:right-[calc(100%-42px)]',
  },
  lg: {
    root: 'h-14 p-1 ps-6 pe-20 text-base hover:ps-20 hover:pe-6 md:text-lg',
    icon: 'right-1.5 h-11 w-11 group-hover:right-[calc(100%-50px)]',
  },
}

const toneClasses: Record<AccentTone, { root: string; icon: string }> = {
  glow: {
    root: 'inline-flex items-center justify-center gap-2 rounded-full border-2 border-[#7c39cf] bg-transparent px-4 py-2 font-semibold text-[#ae89ff] transition-[color,border-color,box-shadow,background-color] duration-300 hover:border-[#c642a5] hover:bg-gradient-to-r hover:from-[#86196b] hover:to-[#5327b3] hover:text-white hover:shadow-[0_0_8px_#c642a5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#c642a5] focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] disabled:pointer-events-none disabled:opacity-60',
    icon: '',
  },
  industrial: {
    root: 'bg-slate-900 text-white hover:bg-amber-500 hover:text-slate-950',
    icon: 'bg-white text-slate-900 group-hover:bg-slate-950 group-hover:text-white',
  },
  'industrial-dark': {
    root: 'bg-amber-500 text-slate-950 hover:bg-white',
    icon: 'bg-white text-slate-950 group-hover:bg-slate-950 group-hover:text-white',
  },
}

/** Botão de ação dos templates: contorno com gradiente (glow) ou ícone deslizante (industrial). */
export function AccentButton({
  children,
  href,
  tone = 'glow',
  size = 'md',
  icon,
  external,
  type = 'button',
  disabled,
  onClick,
  className,
}: AccentButtonProps) {
  const styles = toneClasses[tone]
  const isGlow = tone === 'glow'
  const resolvedIcon = icon ?? <ArrowUpRight className="h-4 w-4 shrink-0" aria-hidden />
  const classes = isGlow
    ? cn(styles.root, size === 'lg' && 'px-6 py-3 text-lg', className)
    : cn(slideBase, slideSizes[size].root, styles.root, className)

  const content = isGlow ? (
    <>
      {icon}
      {children}
    </>
  ) : (
    <>
      <span className="relative z-10 transition-colors duration-500">{children}</span>
      <span
        className={cn(
          'absolute flex items-center justify-center rounded-full transition-all duration-500 group-hover:rotate-12',
          slideSizes[size].icon,
          styles.icon,
        )}
        aria-hidden
      >
        {resolvedIcon}
      </span>
    </>
  )

  if (href) {
    const isExternal = external ?? /^(https?:|mailto:|tel:)/.test(href)
    if (isExternal) {
      return (
        <a
          href={href}
          className={classes}
          onClick={onClick}
          target={href.startsWith('http') ? '_blank' : undefined}
          rel={href.startsWith('http') ? 'noopener noreferrer' : undefined}
        >
          {content}
        </a>
      )
    }
    return (
      <Link href={href} className={classes} onClick={onClick}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
